    if not alphabet:
        raise ValueError("alphabet must contain at least one symbol")
    base = len(alphabet)

    # Determine the digit symbols
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n:
            digits.append(alphabet[n % base])
