def is_ipv4(target):
    """Test if IPv4 address or not

    Parameters:
        target: The address to test. Can be a string, bytes, or an
            ``ipaddress.IPv4Address`` or ``ipaddress.IPv6Address`` instance.

    Returns:
        bool: ``True`` if ``target`` is a valid IPv4 address, ``False`` otherwise.
    """
    # If already an ipaddress instance, check directly
    if isinstance(target, ipaddress.IPv4Address):
        return True
    if isinstance(target, ipaddress.IPv6Address):
        return False
    try:
        addr = ipaddress.ip_address(target)
    except (ValueError, TypeError):
        return False
